    case NotReady
    case ObserverCapacity
    case Reentrant
    case Closing
    case Io(code: Int32?
    )
    case UnsafePath
    case UnsafePermissions
    case UnsupportedPlatform
    case Identity(error: IdentityApiError
    )
    case Storage(reason: ServiceStorageFailure, detail: String
    )
